#!/usr/bin/env python3
"""VBA module writer/injector for the T046 dashboard (xlsx).

Status: EXPERIMENTAL — T046 [xlsx], review requested.

Writing a `.bas` module is portable.  Injecting it into a macro-enabled
workbook needs Windows + Excel + "Trust access to the VBA project object model";
when that gate is closed, the module stays a labelled artifact and the workbook
remains `.xlsx`.  Never silently pretend a macro is embedded.
"""
from __future__ import annotations

from pathlib import Path
import sys

MODULE = r'''Attribute VB_Name = "DashboardTools"
' T046 dashboard helper. Generated by Sheet Forge; review before production.
Option Explicit

Public Sub RefreshDashboard()
    On Error GoTo Failed
    Application.ScreenUpdating = False
    If Not WorksheetExists("Dashboard") Then
        Err.Raise 5, , "Dashboard sheet missing"
    End If
    ' RefreshAll is safe with or without a PivotTable; calculate the model last.
    ThisWorkbook.RefreshAll
    Application.CalculateFullRebuild
    ThisWorkbook.Worksheets("Dashboard").Activate
    Application.ScreenUpdating = True
    MsgBox "Dashboard refreshed.", vbInformation
    Exit Sub
Failed:
    Application.ScreenUpdating = True
    MsgBox "Refresh failed: " & Err.Description, vbExclamation
End Sub

Public Sub FilterAtRisk()
    Dim ws As Worksheet
    If Not WorksheetExists("Data") Then Exit Sub
    Set ws = ThisWorkbook.Worksheets("Data")
    If ws.AutoFilterMode Then ws.AutoFilterMode = False
    ws.Range("A1:K61").AutoFilter Field:=10, Criteria1:="At risk"
End Sub

Private Function WorksheetExists(ByVal name As String) As Boolean
    Dim ws As Worksheet
    On Error Resume Next
    Set ws = ThisWorkbook.Worksheets(name)
    WorksheetExists = Not ws Is Nothing
    On Error GoTo 0
End Function
'''


def write_dashboard_module(path: str | Path) -> Path:
    path = Path(path)
    path.write_text(MODULE, encoding="utf-8")
    return path


def inject_vba(xlsx_path: str | Path, bas_path: str | Path) -> str | None:
    """Inject the module into a copy saved as .xlsm; returns None if blocked."""
    if sys.platform != "win32":
        return None
    try:
        import win32com.client as win32
    except Exception:
        return None
    xlsx_path = Path(xlsx_path).resolve()
    out = xlsx_path.with_suffix(".xlsm")
    excel = wb = None
    try:
        excel = win32.DispatchEx("Excel.Application")
        excel.Visible = False
        excel.DisplayAlerts = False
        wb = excel.Workbooks.Open(str(xlsx_path))
        # This raises if "Trust access to the VBA project object model" is off.
        project = wb.VBProject
        component = project.VBComponents.Add(1)  # vbext_ct_StdModule
        component.Name = "DashboardTools"
        component.CodeModule.AddFromString(Path(bas_path).read_text(encoding="utf-8"))
        wb.SaveAs(str(out), FileFormat=52)  # xlOpenXMLWorkbookMacroEnabled
        return str(out)
    except Exception:
        return None
    finally:
        if wb is not None:
            try:
                wb.Close(False)
            except Exception:
                pass
        if excel is not None:
            try:
                excel.Quit()
            except Exception:
                pass


if __name__ == "__main__":
    import argparse
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("xlsx", type=Path)
    p.add_argument("--bas", type=Path, default=None)
    p.add_argument("--inject", action="store_true")
    args = p.parse_args()
    bas = args.bas or args.xlsx.with_suffix(".bas")
    write_dashboard_module(bas)
    print(f"wrote {bas}")
    if args.inject:
        print(inject_vba(args.xlsx, bas) or "injection blocked or failed")
